CREATE OR REPLACE FUNCTION public.is_admin(_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.admin_users a JOIN auth.users u ON u.id=a.user_id WHERE a.user_id=_uid AND lower(u.email)='teaminosap26@gmail.com' AND u.email_confirmed_at IS NOT NULL) $$;
CREATE OR REPLACE FUNCTION public.claim_first_admin() RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=auth.uid() AND lower(email)='teaminosap26@gmail.com' AND email_confirmed_at IS NOT NULL) THEN RETURN false; END IF; INSERT INTO public.admin_users(user_id,email) VALUES(auth.uid(),'TeamInoSap26@gmail.com') ON CONFLICT(user_id) DO NOTHING; RETURN public.is_admin(auth.uid()); END $$;
ALTER TABLE public.teams ADD CONSTRAINT complete_project_required CHECK (length(btrim(coalesce(name,''))) BETWEEN 1 AND 100 AND length(btrim(coalesce(email,''))) BETWEEN 3 AND 255 AND email ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' AND length(btrim(coalesce(project_title,''))) BETWEEN 1 AND 200 AND length(btrim(coalesce(project_description,''))) BETWEEN 1 AND 10000 AND length(github_url)<=2048 AND coalesce(github_url,'') ~* '^https://(www\.)?github\.com/[^/]+/[^/?#]+/?([?#].*)?$' AND length(website_url)<=2048 AND coalesce(website_url,'') ~* '^https?://[^[:space:]]+' AND length(btrim(coalesce(pdf_path,'')))>0) NOT VALID;
ALTER TABLE public.system_settings ALTER COLUMN max_pdf_mb SET DEFAULT 3;
ALTER TABLE public.system_settings ADD CONSTRAINT pdf_limit_at_most_three CHECK (max_pdf_mb > 0 AND max_pdf_mb <= 3) NOT VALID;
CREATE FUNCTION public.require_project_pdf() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='project-pdfs' AND name=NEW.pdf_path AND (metadata->>'size')::bigint <= 3145728) THEN RAISE EXCEPTION 'A project PDF no larger than 3 MB is required'; END IF; RETURN NEW; END $$;
CREATE TRIGGER require_project_pdf BEFORE INSERT OR UPDATE OF pdf_path ON public.teams FOR EACH ROW EXECUTE FUNCTION public.require_project_pdf();